"""Built-in learning catalog: 6 categories, 34 topics with full workspace content.

This is reference content that is loaded into the database by `app.db.seed`
(idempotent, keyed by slug). The UI reads it through the API.
Resource links should be re-checked from time to time; users can add their own.
"""


def R(title, url, kind="docs"):
    return {"title": title, "url": url, "kind": kind}


def T(slug, title, difficulty, hours, overview, concepts, objectives, resources, exercises, mini, questions, criteria):
    return dict(
        slug=slug, title=title, difficulty=difficulty, estimated_hours=hours, overview=overview,
        concepts=concepts, objectives=objectives, recommended_resources=resources,
        exercises=exercises, mini_project=mini, interview_questions=questions, completion_criteria=criteria,
    )


